/**
 * assets.js — sprite cắt từ ảnh tham chiếu rhythm-hack.png (data URL
 * WebP): 4 note pill neon theo màu lane, 4 receptor flare (cột sáng +
 * vòng nhận + hạt pixel), trái tim pixel SYSTEM REPAIR, texture mạch
 * nền. Flare/note có alpha (darkkey) để blend cộng sáng trên highway.
 */

export const ASSETS = {
  noteCyan:
    "data:image/webp;base64,",
  noteViolet:
    "data:image/webp;base64,",
  notePink:
    "data:image/webp;base64,",
  noteLime:
    "data:image/webp;base64,",
  flareCyan:
    "data:image/webp;base64,",
  flareViolet:
    "data:image/webp;base64,",
  flarePink:
    "data:image/webp;base64,",
  flareLime:
    "data:image/webp;base64,",
  heart:
    "data:image/webp;base64,",
  bgTile:
    "data:image/webp;base64,",
};

/** Tạo và decode Image cho toàn bộ ASSETS; trả về map name → HTMLImageElement. */
export function loadImages() {
  const out = {};
  for (const [k, v] of Object.entries(ASSETS)) {
    const im = new Image();
    im.decoding = "async";
    im.src = v;
    out[k] = im;
  }
  return out;
}

/** Ảnh đã sẵn sàng vẽ chưa (decode xong, hợp lệ). */
export const ready = (im) => !!(im && im.complete && im.naturalWidth > 0);
